tasks.command:
$root = 'd:\Code\Perso\DnDFightTool'
$files = Get-ChildItem -Path $root -Include '*.cs','*.razor' -Recurse -File | Where-Object { $_.FullName -notmatch '\\(bin|obj)\\' -and $_.FullName -notmatch '\\Dices\\(DiceRollTemplate|DiceRollModifiersTemplate|D20BaseRollResult|RawD20RollResult|ModifiedD20RollResult|HitRollResult|IDiceRollResult|Wildcard)\.cs$' -and $_.FullName -notmatch '\\Dices\\Validation\\' -and $_.FullName -notmatch '\\ArmorClasses\\ArmorClass\.cs$' -and $_.FullName -notmatch '\\ArmorClasses\\Validation\\' }
$replacements = @(
  @('using DnDFightTool.Domain.DnDEntities.Dices.DiceThrows.Validation;', 'using DnDFightTool.Domain.DnDEntities.Dices.Validation;'),
  @('using DnDFightTool.Domain.DnDEntities.Dices.DiceThrows;', 'using DnDFightTool.Domain.DnDEntities.Dices;'),
  @('using DnDFightTool.Domain.DnDEntities.AttackRolls.ArmorClasses.Validation;', 'using DnDFightTool.Domain.DnDEntities.ArmorClasses.Validation;'),
  @('using DnDFightTool.Domain.DnDEntities.AttackRolls.ArmorClasses;', 'using DnDFightTool.Domain.DnDEntities.ArmorClasses;'),
  @('DiceThrowModifiersTemplate', 'DiceRollModifiersTemplate'),
  @('DiceThrowTemplate', 'DiceRollTemplate'),
  @('DiceThrowTemplateValidator', 'DiceRollTemplateValidator'),
  @('IRollResult', 'IDiceRollResult')
)
$count = 0
foreach ($f in $files) {
  $content = Get-Content $f.FullName -Raw
  $original = $content
  foreach ($r in $replacements) {
    $content = $content.Replace($r[0], $r[1])
  }
  if ($content -ne $original) {
    Set-Content $f.FullName -Value $content -NoNewline
    $count++
    Write-Host "Updated: $($f.FullName)"
  }
}
Write-Host "Total files updated: $count"
